     1→import { existsSync } from "fs";
     2→import { writeFile } from "fs/promises";
     3→import { homedir } from "os";
     4→import path, { join } from "path";
     5→import { initConfig, initDir, cleanupLogFiles } from "./utils";
     6→import { createServer } from "./server";
     7→import { router } from "./utils/router";
     8→import { apiKeyAuth } from "./middleware/auth";
     9→import {
    10→  cleanupPidFile,
    11→  isServiceRunning,
    12→  savePid,
    13→} from "./utils/processCheck";
    14→import { CONFIG_FILE } from "./constants";
    15→import { createStream } from 'rotating-file-stream';
    16→import { HOME_DIR } from "./constants";
    17→import { sessionUsageCache } from "./utils/cache";
    18→import { SSEParserTransform } from "./utils/SSEParser.transform";
    19→import { SSESerializerTransform } from "./utils/SSESerializer.transform";
    20→import { rewriteStream } from "./utils/rewriteStream";
    21→import JSON5 from "json5";
    22→import { IAgent } from "./agents/type";
    23→import agentsManager from "./agents";
    24→import { EventEmitter } from "node:events";
    25→import { logClaudeCodeRequest, logClaudeCodeResponse } from "./utils/requestLogger";
    26→import { logToWorkspace } from "./utils/customLogger";
    27→
    28→const event = new EventEmitter()
    29→
    30→async function initializeClaudeConfig() {
    31→  const homeDir = homedir();
    32→  const configPath = join(homeDir, ".claude.json");
    33→  if (!existsSync(configPath)) {
    34→    const userID = Array.from(
    35→      { length: 64 },
    36→      () => Math.random().toString(16)[2]
    37→    ).join("");
    38→    const configContent = {
    39→      numStartups: 184,
    40→      autoUpdaterStatus: "enabled",
    41→      userID,
    42→      hasCompletedOnboarding: true,
    43→      lastOnboardingVersion: "1.0.17",
    44→      projects: {},
    45→    };
    46→    await writeFile(configPath, JSON.stringify(configContent, null, 2));
    47→  }
    48→}
    49→
    50→interface RunOptions {
    51→  port?: number;
    52→}
    53→
    54→async function run(options: RunOptions = {}) {
    55→  // Check if service is already running
    56→  const isRunning = await isServiceRunning()
    57→  if (isRunning) {
    58→    console.log("✅ Service is already running in the background.");
    59→    return;
    60→  }
    61→
    62→  await initializeClaudeConfig();
    63→  await initDir();
    64→  // Clean up old log files, keeping only the 10 most recent ones
    65→  await cleanupLogFiles();
    66→  const config = await initConfig();
    67→
    68→
    69→  let HOST = config.HOST || "127.0.0.1";
    70→
    71→  if (config.HOST && !config.APIKEY) {
    72→    HOST = "127.0.0.1";
    73→    console.warn("⚠️ API key is not set. HOST is forced to 127.0.0.1.");
    74→  }
    75→
    76→  const port = config.PORT || 3456;
    77→
    78→  // Save the PID of the background process
    79→  savePid(process.pid);
    80→
    81→  // Handle SIGINT (Ctrl+C) to clean up PID file
    82→  process.on("SIGINT", () => {
    83→    console.log("Received SIGINT, cleaning up...");
    84→    cleanupPidFile();
    85→    process.exit(0);
    86→  });
    87→
    88→  // Handle SIGTERM to clean up PID file
    89→  process.on("SIGTERM", () => {
    90→    cleanupPidFile();
    91→    process.exit(0);
    92→  });
    93→
    94→  // Use port from environment variable if set (for background process)
    95→  const servicePort = process.env.SERVICE_PORT
    96→    ? parseInt(process.env.SERVICE_PORT)
    97→    : port;
    98→
    99→  // Configure logger based on config settings
   100→  const pad = num => (num > 9 ? "" : "0") + num;
   101→  const generator = (time, index) => {
   102→    if (!time) {
   103→      time = new Date()
   104→    }
   105→
   106→    var month = time.getFullYear() + "" + pad(time.getMonth() + 1);
   107→    var day = pad(time.getDate());
   108→    var hour = pad(time.getHours());
   109→    var minute = pad(time.getMinutes());
   110→
   111→    return `./logs/ccr-${month}${day}${hour}${minute}${pad(time.getSeconds())}${index ? `_${index}` : ''}.log`;
   112→  };
   113→  const loggerConfig =
   114→    config.LOG !== false
   115→      ? {
   116→        level: config.LOG_LEVEL || "debug",
   117→        stream: createStream(generator, {
   118→          path: HOME_DIR,
   119→          maxFiles: 3,
   120→          interval: "1d",
   121→          compress: false,
   122→          maxSize: "50M"
   123→        }),
   124→      }
   125→      : false;
   126→
   127→  const server = createServer({
   128→    jsonPath: CONFIG_FILE,
   129→    initialConfig: {
   130→      // ...config,
   131→      providers: config.Providers || config.providers,
   132→      HOST: HOST,
   133→      PORT: servicePort,
   134→      LOG_FILE: join(
   135→        homedir(),
   136→        ".claude-code-router",
   137→        "claude-code-router.log"
   138→      ),
   139→    },
   140→    logger: loggerConfig,
   141→  });
   142→
   143→  // Add global error handlers to prevent the service from crashing
   144→  process.on("uncaughtException", (err) => {
   145→    server.logger.error("Uncaught exception:", err);
   146→  });
   147→
   148→  process.on("unhandledRejection", (reason, promise) => {
   149→    server.logger.error("Unhandled rejection at:", promise, "reason:", reason);
   150→  });
   151→  // Add async preHandler hook for authentication
   152→  server.addHook("preHandler", async (req, reply) => {
   153→    return new Promise((resolve, reject) => {
   154→      const done = (err?: Error) => {
   155→        if (err) reject(err);
   156→        else resolve();
   157→      };
   158→      // Call the async auth function
   159→      apiKeyAuth(config)(req, reply, done).catch(reject);
   160→    });
   161→  });
   162→  server.addHook("preHandler", async (req, reply) => {
   163→    if (req.url.startsWith("/v1/messages") && !req.url.startsWith("/v1/messages/count_tokens")) {
   164→      const useAgents = []
   165→
   166→      for (const agent of agentsManager.getAllAgents()) {
   167→        if (agent.shouldHandle(req, config)) {
   168→          // 设置agent标识
   169→          useAgents.push(agent.name)
   170→
   171→          // change request body
   172→          agent.reqHandler(req, config);
   173→
   174→          // append agent tools
   175→          if (agent.tools.size) {
   176→            if (!req.body?.tools?.length) {
   177→              req.body.tools = []
   178→            }
   179→            req.body.tools.unshift(...Array.from(agent.tools.values()).map(item => {
   180→              return {
   181→                name: item.name,
   182→                description: item.description,
   183→                input_schema: item.input_schema
   184→              }
   185→            }))
   186→          }
   187→        }
   188→      }
   189→
   190→      if (useAgents.length) {
   191→        req.agents = useAgents;
   192→      }
   193→      await router(req, reply, {
   194→        config,
   195→        event
   196→      });
   197→
   198→      // Log the original request after routing (model selection is complete)
   199→      await logClaudeCodeRequest(req, config);
   200→      await logToWorkspace(req);
   201→    }
   202→  });
   203→  server.addHook("onError", async (request, reply, error) => {
   204→    event.emit('onError', request, reply, error);
   205→  })
   206→  server.addHook("onSend", (req, reply, payload, done) => {
   207→    if (req.sessionId && req.url.startsWith("/v1/messages") && !req.url.startsWith("/v1/messages/count_tokens")) {
   208→      if (payload instanceof ReadableStream) {
   209→        if (req.agents) {
   210→          const abortController = new AbortController();
   211→          const eventStream = payload.pipeThrough(new SSEParserTransform())
   212→          let currentAgent: undefined | IAgent;
   213→          let currentToolIndex = -1
   214→          let currentToolName = ''
   215→          let currentToolArgs = ''
   216→          let currentToolId = ''
   217→          const toolMessages: any[] = []
   218→          const assistantMessages: any[] = []
   219→          // 存储Anthropic格式的消息体，区分文本和工具类型
   220→          return done(null, rewriteStream(eventStream, async (data, controller) => {
   221→            try {
   222→              // 检测工具调用开始
   223→              if (data.event === 'content_block_start' && data?.data?.content_block?.name) {
   224→                const agent = req.agents.find((name: string) => agentsManager.getAgent(name)?.tools.get(data.data.content_block.name))
   225→                if (agent) {
   226→                  currentAgent = agentsManager.getAgent(agent)
   227→                  currentToolIndex = data.data.index
   228→                  currentToolName = data.data.content_block.name
   229→                  currentToolId = data.data.content_block.id
   230→                  return undefined;
   231→                }
   232→              }
   233→
   234→              // 收集工具参数
   235→              if (currentToolIndex > -1 && data.data.index === currentToolIndex && data.data?.delta?.type === 'input_json_delta') {
   236→                currentToolArgs += data.data?.delta?.partial_json;
   237→                return undefined;
   238→              }
   239→
   240→              // 工具调用完成，处理agent调用
   241→              if (currentToolIndex > -1 && data.data.index === currentToolIndex && data.data.type === 'content_block_stop') {
   242→                try {
   243→                  const args = JSON5.parse(currentToolArgs);
   244→                  assistantMessages.push({
   245→                    type: "tool_use",
   246→                    id: currentToolId,
   247→                    name: currentToolName,
   248→                    input: args
   249→                  })
   250→                  const toolResult = await currentAgent?.tools.get(currentToolName)?.handler(args, {
   251→                    req,
   252→                    config
   253→                  });
   254→                  toolMessages.push({
   255→                    "tool_use_id": currentToolId,
   256→                    "type": "tool_result",
   257→                    "content": toolResult
   258→                  })
   259→                  currentAgent = undefined
   260→                  currentToolIndex = -1
   261→                  currentToolName = ''
   262→                  currentToolArgs = ''
   263→                  currentToolId = ''
   264→                } catch (e) {
   265→                  console.log(e);
   266→                }
   267→                return undefined;
   268→              }
   269→
   270→              if (data.event === 'message_delta' && toolMessages.length) {
   271→                req.body.messages.push({
   272→                  role: 'assistant',
   273→                  content: assistantMessages
   274→                })
   275→                req.body.messages.push({
   276→                  role: 'user',
   277→                  content: toolMessages
   278→                })
   279→                const response = await fetch(`http://127.0.0.1:${config.PORT || 3456}/v1/messages`, {
   280→                  method: "POST",
   281→                  headers: {
   282→                    'x-api-key': config.APIKEY,
   283→                    'content-type': 'application/json',
   284→                  },
   285→                  body: JSON.stringify(req.body),
   286→                })
   287→                if (!response.ok) {
   288→                  return undefined;
   289→                }
   290→                const stream = response.body!.pipeThrough(new SSEParserTransform())
   291→                const reader = stream.getReader()
   292→                while (true) {
   293→                  try {
   294→                    const { value, done } = await reader.read();
   295→                    if (done) {
   296→                      break;
   297→                    }
   298→                    if (['message_start', 'message_stop'].includes(value.event)) {
   299→                      continue
   300→                    }
   301→
   302→                    // 检查流是否仍然可写
   303→                    if (!controller.desiredSize) {
   304→                      break;
   305→                    }
   306→
   307→                    controller.enqueue(value)
   308→                  } catch (readError: any) {
   309→                    if (readError.name === 'AbortError' || readError.code === 'ERR_STREAM_PREMATURE_CLOSE') {
   310→                      abortController.abort(); // 中止所有相关操作
   311→                      break;
   312→                    }
   313→                    throw readError;
   314→                  }
   315→
   316→                }
   317→                return undefined
   318→              }
   319→              return data
   320→            } catch (error: any) {
   321→              console.error('Unexpected error in stream processing:', error);
   322→
   323→              // 处理流提前关闭的错误
   324→              if (error.code === 'ERR_STREAM_PREMATURE_CLOSE') {
   325→                abortController.abort();
   326→                return undefined;
   327→              }
   328→
   329→              // 其他错误仍然抛出
   330→              throw error;
   331→            }
   332→          }).pipeThrough(new SSESerializerTransform()))
   333→        }
   334→
   335→        const [originalStream, clonedStream] = payload.tee();
   336→        const read = async (stream: ReadableStream) => {
   337→          const reader = stream.getReader();
   338→          try {
   339→            while (true) {
   340→              const { done, value } = await reader.read();
   341→              if (done) break;
   342→              // Process the value if needed
   343→              const dataStr = new TextDecoder().decode(value);
   344→              if (!dataStr.startsWith("event: message_delta")) {
   345→                continue;
   346→              }
   347→              const str = dataStr.slice(27);
   348→              try {
   349→                const message = JSON.parse(str);
   350→                sessionUsageCache.put(req.sessionId, message.usage);
   351→              } catch { }
   352→            }
   353→          } catch (readError: any) {
   354→            if (readError.name === 'AbortError' || readError.code === 'ERR_STREAM_PREMATURE_CLOSE') {
   355→              console.error('Background read stream closed prematurely');
   356→            } else {
   357→              console.error('Error in background stream reading:', readError);
   358→            }
   359→          } finally {
   360→            reader.releaseLock();
   361→          }
   362→        }
   363→        read(clonedStream);
   364→        return done(null, originalStream)
   365→      }
   366→      sessionUsageCache.put(req.sessionId, payload.usage);
   367→
   368→      // Log the response (non-streaming only)
   369→      if (typeof payload === 'object' && !payload.error) {
   370→        logClaudeCodeResponse(req, payload, config).catch(err => {
   371→          server.logger?.error('Failed to log response:', err);
   372→        });
   373→      }
   374→
   375→      if (typeof payload === 'object') {
   376→        if (payload.error) {
   377→          return done(payload.error, null)
   378→        } else {
   379→          return done(payload, null)
   380→        }
   381→      }
   382→    }
   383→    if (typeof payload === 'object' && payload.error) {
   384→      return done(payload.error, null)
   385→    }
   386→    done(null, payload)
   387→  });
   388→  server.addHook("onSend", async (req, reply, payload) => {
   389→    event.emit('onSend', req, reply, payload);
   390→    return payload;
   391→  })
   392→
   393→
   394→  server.start();
   395→}
   396→
   397→export { run };
