1→import Server from "@musistudio/llms";
     2→import { readConfigFile, writeConfigFile, backupConfigFile } from "./utils";
     3→import { checkForUpdates, performUpdate } from "./utils";
     4→import { join } from "path";
     5→import fastifyStatic from "@fastify/static";
     6→import { readdirSync, statSync, readFileSync, writeFileSync, existsSync } from "fs";
     7→import { homedir } from "os";
     8→import {calculateTokenCount} from "./utils/router";
     9→
    10→export const createServer = (config: any): Server => {
    11→  const server = new Server(config);
    12→
    13→  server.app.post("/v1/messages/count_tokens", async (req, reply) => {
    14→    const {messages, tools, system} = req.body;
    15→    const tokenCount = calculateTokenCount(messages, system, tools);
    16→    return { "input_tokens": tokenCount }
    17→  });
    18→
    19→  // Add endpoint to read config.json with access control
    20→  server.app.get("/api/config", async (req, reply) => {
    21→    return await readConfigFile();
    22→  });
    23→
    24→  server.app.get("/api/transformers", async () => {
    25→    const transformers =
    26→      server.app._server!.transformerService.getAllTransformers();
    27→    const transformerList = Array.from(transformers.entries()).map(
    28→      ([name, transformer]: any) => ({
    29→        name,
    30→        endpoint: transformer.endPoint || null,
    31→      })
    32→    );
    33→    return { transformers: transformerList };
    34→  });
    35→
    36→  // Add endpoint to save config.json with access control
    37→  server.app.post("/api/config", async (req, reply) => {
    38→    const newConfig = req.body;
    39→
    40→    // Backup existing config file if it exists
    41→    const backupPath = await backupConfigFile();
    42→    if (backupPath) {
    43→      console.log(`Backed up existing configuration file to ${backupPath}`);
    44→    }
    45→
    46→    await writeConfigFile(newConfig);
    47→    return { success: true, message: "Config saved successfully" };
    48→  });
    49→
    50→  // Add endpoint to restart the service with access control
    51→  server.app.post("/api/restart", async (req, reply) => {
    52→    reply.send({ success: true, message: "Service restart initiated" });
    53→
    54→    // Restart the service after a short delay to allow response to be sent
    55→    setTimeout(() => {
    56→      const { spawn } = require("child_process");
    57→      spawn(process.execPath, [process.argv[1], "restart"], {
    58→        detached: true,
    59→        stdio: "ignore",
    60→      });
    61→    }, 1000);
    62→  });
    63→
    64→  // Register static file serving with caching
    65→  server.app.register(fastifyStatic, {
    66→    root: join(__dirname, "..", "dist"),
    67→    prefix: "/ui/",
    68→    maxAge: "1h",
    69→  });
    70→
    71→  // Redirect /ui to /ui/ for proper static file serving
    72→  server.app.get("/ui", async (_, reply) => {
    73→    return reply.redirect("/ui/");
    74→  });
    75→
    76→  // 版本检查端点
    77→  server.app.get("/api/update/check", async (req, reply) => {
    78→    try {
    79→      // 获取当前版本
    80→      const currentVersion = require("../package.json").version;
    81→      const { hasUpdate, latestVersion, changelog } = await checkForUpdates(currentVersion);
    82→
    83→      return {
    84→        hasUpdate,
    85→        latestVersion: hasUpdate ? latestVersion : undefined,
    86→        changelog: hasUpdate ? changelog : undefined
    87→      };
    88→    } catch (error) {
    89→      console.error("Failed to check for updates:", error);
    90→      reply.status(500).send({ error: "Failed to check for updates" });
    91→    }
    92→  });
    93→
    94→  // 执行更新端点
    95→  server.app.post("/api/update/perform", async (req, reply) => {
    96→    try {
    97→      // 只允许完全访问权限的用户执行更新
    98→      const accessLevel = (req as any).accessLevel || "restricted";
    99→      if (accessLevel !== "full") {
   100→        reply.status(403).send("Full access required to perform updates");
   101→        return;
   102→      }
   103→
   104→      // 执行更新逻辑
   105→      const result = await performUpdate();
   106→
   107→      return result;
   108→    } catch (error) {
   109→      console.error("Failed to perform update:", error);
   110→      reply.status(500).send({ error: "Failed to perform update" });
   111→    }
   112→  });
   113→
   114→  // 获取日志文件列表端点
   115→  server.app.get("/api/logs/files", async (req, reply) => {
   116→    try {
   117→      const logDir = join(homedir(), ".claude-code-router", "logs");
   118→      const logFiles: Array<{ name: string; path: string; size: number; lastModified: string }> = [];
   119→
   120→      if (existsSync(logDir)) {
   121→        const files = readdirSync(logDir);
   122→
   123→        for (const file of files) {
   124→          if (file.endsWith('.log')) {
   125→            const filePath = join(logDir, file);
   126→            const stats = statSync(filePath);
   127→
   128→            logFiles.push({
   129→              name: file,
   130→              path: filePath,
   131→              size: stats.size,
   132→              lastModified: stats.mtime.toISOString()
   133→            });
   134→          }
   135→        }
   136→
   137→        // 按修改时间倒序排列
   138→        logFiles.sort((a, b) => new Date(b.lastModified).getTime() - new Date(a.lastModified).getTime());
   139→      }
   140→
   141→      return logFiles;
   142→    } catch (error) {
   143→      console.error("Failed to get log files:", error);
   144→      reply.status(500).send({ error: "Failed to get log files" });
   145→    }
   146→  });
   147→
   148→  // 获取日志内容端点
   149→  server.app.get("/api/logs", async (req, reply) => {
   150→    try {
   151→      const filePath = (req.query as any).file as string;
   152→      let logFilePath: string;
   153→
   154→      if (filePath) {
   155→        // 如果指定了文件路径，使用指定的路径
   156→        logFilePath = filePath;
   157→      } else {
   158→        // 如果没有指定文件路径，使用默认的日志文件路径
   159→        logFilePath = join(homedir(), ".claude-code-router", "logs", "app.log");
   160→      }
   161→
   162→      if (!existsSync(logFilePath)) {
   163→        return [];
   164→      }
   165→
   166→      const logContent = readFileSync(logFilePath, 'utf8');
   167→      const logLines = logContent.split('\n').filter(line => line.trim())
   168→
   169→      return logLines;
   170→    } catch (error) {
   171→      console.error("Failed to get logs:", error);
   172→      reply.status(500).send({ error: "Failed to get logs" });
   173→    }
   174→  });
   175→
   176→  // 清除日志内容端点
   177→  server.app.delete("/api/logs", async (req, reply) => {
   178→    try {
   179→      const filePath = (req.query as any).file as string;
   180→      let logFilePath: string;
   181→
   182→      if (filePath) {
   183→        // 如果指定了文件路径，使用指定的路径
   184→        logFilePath = filePath;
   185→      } else {
   186→        // 如果没有指定文件路径，使用默认的日志文件路径
   187→        logFilePath = join(homedir(), ".claude-code-router", "logs", "app.log");
   188→      }
   189→
   190→      if (existsSync(logFilePath)) {
   191→        writeFileSync(logFilePath, '', 'utf8');
   192→      }
   193→
   194→      return { success: true, message: "Logs cleared successfully" };
   195→    } catch (error) {
   196→      console.error("Failed to clear logs:", error);
   197→      reply.status(500).send({ error: "Failed to clear logs" });
   198→    }
   199→  });
   200→
   201→  return server;
   202→};
